import type { Candle } from "./types.ts"

/**
 * Original synthetic daily OHLC created for this demo.
 * Dedicated to the public domain under CC0 1.0.
 * Not a recording of SPY, QQQ, or any exchange, and not a TradingKit or broker feed.
 */
export const SAMPLE_LICENSE =
  "Original synthetic OHLC generated by a fixed seed for this demo and dedicated to the public domain under CC0 1.0. Bars are weekdays from the generator, not an exchange calendar. It is not a market recording and not a live TradingKit, broker, or exchange feed."

export const SAMPLE_DATA_NOTE = `Bundled SAMPLE-SPY and SAMPLE-QQQ candles are daily sample series. ${SAMPLE_LICENSE}`

const BAR_COUNT = 756
const START = "2022-01-03"

type SeriesId = "SAMPLE-SPY" | "SAMPLE-QQQ"

function mulberry32(seed: number): () => number {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) | 0
    let t = Math.imul(state ^ (state >>> 15), 1 | state)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function businessDays(startIso: string, count: number): string[] {
  const parts = startIso.split("-").map(Number)
  const year = parts[0] ?? 2022
  const month = parts[1] ?? 1
  const day = parts[2] ?? 3
  const cursor = new Date(Date.UTC(year, month - 1, day))
  const dates: string[] = []
  while (dates.length < count) {
    const weekday = cursor.getUTCDay()
    if (weekday !== 0 && weekday !== 6) {
      const yyyy = cursor.getUTCFullYear()
      const mm = String(cursor.getUTCMonth() + 1).padStart(2, "0")
      const dd = String(cursor.getUTCDate()).padStart(2, "0")
      dates.push(`${yyyy}-${mm}-${dd}`)
    }
    cursor.setUTCDate(cursor.getUTCDate() + 1)
  }
  return dates
}

function round(value: number): number {
  return Math.round(value * 10000) / 10000
}

function driftAt(index: number): number {
  const cycle = ((index % 260) + 260) % 260
  if (cycle < 80) return 0.0024
  if (cycle < 140) return -0.0028
  if (cycle < 200) return 0.0018
  return -0.0006
}

function buildSeries(seriesId: SeriesId): Candle[] {
  const rand = mulberry32(seriesId === "SAMPLE-SPY" ? 20241113 : 20241199)
  const dates = businessDays(START, BAR_COUNT)
  const phase = seriesId === "SAMPLE-QQQ" ? 35 : 0
  let price = seriesId === "SAMPLE-SPY" ? 420 : 318
  const candles: Candle[] = []
  for (let i = 0; i < dates.length; i++) {
    const open = price
    const shock = (rand() - 0.5) * 0.02
    const close = round(Math.max(15, open * (1 + driftAt(i + phase) + shock)))
    const top = Math.max(open, close)
    const bottom = Math.min(open, close)
    const high = round(top * (1 + rand() * 0.004))
    const low = round(Math.max(1, bottom * (1 - rand() * 0.004)))
    const date = dates[i] ?? START
    candles.push({ date, open: round(open), high, low, close })
    price = close
  }
  return candles
}

const cache = new Map<SeriesId, Candle[]>()

export function getSeries(seriesId: SeriesId): Candle[] {
  const cached = cache.get(seriesId)
  if (cached) return cached
  const built = buildSeries(seriesId)
  cache.set(seriesId, built)
  return built
}

export function seriesForSymbol(symbol: string): {
  symbol: string
  seriesId: SeriesId
  candles: Candle[]
  note: string
} {
  const upper = symbol.trim().toUpperCase()
  const useQqq = upper === "QQQ" || upper === "SAMPLE-QQQ"
  const seriesId: SeriesId = useQqq ? "SAMPLE-QQQ" : "SAMPLE-SPY"
  const known =
    upper === "SPY" ||
    upper === "QQQ" ||
    upper === "SAMPLE-SPY" ||
    upper === "SAMPLE-QQQ" ||
    upper === "SAMPLE"
  const note = known
    ? `${upper} is backtested on bundled ${seriesId} daily candles. ${SAMPLE_DATA_NOTE}`
    : `${upper || "This symbol"} is not in the bundle. The backtest uses ${seriesId} as a stand-in. ${SAMPLE_DATA_NOTE}`
  return { symbol: upper || "SPY", seriesId, candles: getSeries(seriesId), note }
}
